// Offline app shell (beta 0.9.3). Generated by scripts/build.mjs — edit web/sw.js.
// Live (/logbook/) and beta (/logbook/beta/) share one origin: each worker keeps to its own cache and files.
const CHANNEL = "beta";
const CACHE = "logbook-beta-0.9.3";
const SHELL = ["./","./index.html","./styles.css","./manifest.webmanifest","./js/app.js","./js/channel.js","./js/data.js","./js/db.js","./js/domain.js","./js/i18n.js","./js/importer.js","./js/seed.js","./js/share.js","./icons/icon-192.png","./icons/apple-touch-icon.png"];
const mine = k => k.startsWith("logbook-" + CHANNEL + "-") || (CHANNEL === "live" && /^logbook-\d/.test(k));   // old live caches
self.addEventListener("install", e => { e.waitUntil(caches.open(CACHE).then(c => c.addAll(SHELL)).then(() => self.skipWaiting())); });
self.addEventListener("activate", e => {
  e.waitUntil(caches.keys().then(ks => Promise.all(ks.filter(k => k !== CACHE && mine(k)).map(k => caches.delete(k)))).then(() => self.clients.claim()));
});
self.addEventListener("fetch", e => {
  const req = e.request, url = new URL(req.url);
  if (req.method !== "GET" || url.origin !== location.origin) return;
  if (CHANNEL === "live" && url.pathname.includes("/beta/")) return;          // the beta has its own worker
  e.respondWith(caches.match(req, { ignoreSearch: true }).then(hit => {
    const net = fetch(req).then(res => { if (res && res.ok) { const copy = res.clone(); caches.open(CACHE).then(c => c.put(req, copy)); } return res; }).catch(() => hit);
    return hit || net;
  }));
});
